const plantMat = PM;
const FL = .3, TER = .28;              // house floor and terrace level above the garden
function lam(color, o = {}) { return new THREE.MeshLambertMaterial({ color, ...o }); }
function std(color, o = {}) { return new THREE.MeshStandardMaterial({ color, roughness: .85, ...o }); }
let target = scene;
function add(mesh, cast = true, recv = true) { mesh.castShadow = cast; mesh.receiveShadow = recv; target.add(mesh); return mesh; }
function box(x0, y0, x1, y1, yb, h, mat, cast = true) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(Math.abs(x1 - x0), h, Math.abs(y1 - y0)), mat);
  m.position.set(wx((x0 + x1) / 2), yb + h / 2, wz((y0 + y1) / 2)); return add(m, cast);
}
const shapeOf = poly => new THREE.Shape(poly.map(([x, y]) => new THREE.Vector2(wx(x), -wz(y))));
function surface(poly, y, mat) { const g = new THREE.ShapeGeometry(shapeOf(poly)); g.rotateX(-Math.PI / 2); const m = new THREE.Mesh(g, mat); m.position.y = y; return add(m, false, true); }
function slab(poly, y, h, mat, cast = true) { const g = new THREE.ExtrudeGeometry(shapeOf(poly), { depth: h, bevelEnabled: false }); g.rotateX(-Math.PI / 2); const m = new THREE.Mesh(g, mat); m.position.y = y; return add(m, cast, true); }
const rect = (x0, y0, x1, y1) => [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
const circlePoly = (cx, cy, r, n = 48, clipX = 99) => Array.from({ length: n }, (_, i) => [Math.min(clipX, cx + Math.cos(i / n * TAU) * r), cy + Math.sin(i / n * TAU) * r]);

/* textures */
function tex(px, metres, draw) {
  const c = document.createElement('canvas'); c.width = c.height = px; const g = c.getContext('2d'); draw(g, px);
  const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(1 / metres, 1 / metres);
  t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = Math.min(8, 8); return t;
}
function speckle(g, px, base, cols, n, sz) { g.fillStyle = base; g.fillRect(0, 0, px, px); for (let i = 0; i < n; i++) { g.fillStyle = cols[i % cols.length]; const s = sz * (.4 + rnd()); g.fillRect(rnd() * px, rnd() * px, s, s); } }
const tLawn = tex(512, 4, (g, px) => { speckle(g, px, '#6f9b47', ['#7fab52', '#62893e', '#86b25a', '#5a8239'], 9000, 3); g.fillStyle = 'rgba(255,255,255,.05)'; g.fillRect(0, 0, px / 2, px); });
