const tGravel = tex(256, 2, (g, px) => speckle(g, px, '#cfc8bb', ['#b8b0a2', '#ddd7cc', '#a79f92', '#e6e0d6'], 9000, 2.6));
function bricks(bw, bh, cols, joint, jw = 3) { return (g, px) => { g.fillStyle = joint; g.fillRect(0, 0, px, px); for (let r = 0, y = 0; y < px; y += bh, r++) for (let x = -(r % 2) * bw / 2; x < px; x += bw) { g.fillStyle = cols[Math.floor(rnd() * cols.length)]; g.fillRect(x + jw / 2, y + jw / 2, bw - jw, bh - jw); } }; }
