function vegBox(cx, cy, w, d) { box(cx - w / 2, cy - d / 2, cx + w / 2, cy + d / 2, .03, .4, mWood); box(cx - w / 2 + .07, cy - d / 2 + .07, cx + w / 2 - .07, cy + d / 2 - .07, .38, .03, lam('#3b2a1d'), false);
  for (let i = 0; i < Math.round(w * d * 6); i++) { const x = cx + R(-w / 2 + .15, w / 2 - .15), y = cy + R(-d / 2 + .15, d / 2 - .15); const m = new THREE.Mesh(L(i), lam(rnd() < .8 ? '#6fa640' : '#93424f')); m.scale.set(.13, .1, .13); m.position.set(wx(x), .47, wz(y)); target.add(m); } }
function hammock(x0, y0, x1, y1) {
  const a = new THREE.Vector3(wx(x0), 0, wz(y0)), b = new THREE.Vector3(wx(x1), 0, wz(y1));
  const mid = a.clone().add(b).multiplyScalar(.5), len = a.distanceTo(b), ang = -Math.atan2(b.z - a.z, b.x - a.x);
  const grp = new THREE.Group(); grp.position.copy(mid); grp.rotation.y = ang; target.add(grp);
  const beam = (x, y, z, sx, sy, sz, rz = 0) => { const m = new THREE.Mesh(new THREE.BoxGeometry(sx, sy, sz), mWood); m.position.set(x, y, z); m.rotation.z = rz; m.castShadow = true; grp.add(m); };
  beam(0, .06, 0, len - .2, .1, .12); beam(-len / 2 + .35, .75, 0, .1, 1.6, .1, -.45); beam(len / 2 - .35, .75, 0, .1, 1.6, .1, .45);
  const g = new THREE.PlaneGeometry(len - 1.0, .95, 16, 2); const p = g.attributes.position;
  for (let i = 0; i < p.count; i++) { const x = p.getX(i), y = p.getY(i), t = x / ((len - 1.0) / 2); p.setXYZ(i, x, 1.05 - .45 * (1 - t * t), y * (.6 + .4 * (1 - t * t))); }
  g.computeVertexNormals(); const h = new THREE.Mesh(g, lam('#d9734f', { side: THREE.DoubleSide })); h.castShadow = true; grp.add(h);
}

function inPoly(x, y, poly) { let c = false; for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) { const [xi, yi] = poly[i], [xj, yj] = poly[j]; if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c; } return c; }
const built = {};
const show = k => { if (!built[k]) built[k] = CONCEPTS[k](); for (const c in built) built[c].group.visible = +c === +k; };
return { root: ROOT, show, names: { 1: 'Koncepcja I', 2: 'Koncepcja II', 3: 'Propozycja Claude' } };
